window.addEventListener("CookiebotOnConsentReady", () => {
	let consent = [];
	if(Cookiebot.consent.necessary) {
		consent.push(0);
	}
	if(Cookiebot.consent.preferences) {
		consent.push(1);
	}
	if(Cookiebot.consent.statistics) {
		consent.push(2);
	}
	if(Cookiebot.consent.marketing) {
		consent.push(3);
	}
	window.bCookies.setConsent(consent);
});

if(typeof window.__b_render_cb === `undefined`) {
	window.__b_render_cb = function() {
		let t = document.getElementById("CookieBotDeclaration");
		if(!t) {
			return;
		}
		let s = document.createElement("script");
		s.id = "CookieDeclaration";
		s.src = t.getAttribute("data-src");
		s.setAttribute("data-culture", "EN");
		t.parentNode.insertBefore(s,t);
	}
}
window.bPlanner.on("pageFinishLoading", () => {
	window.__b_render_cb();
}, "CookiebotRenderDeclaration", true);
